    console.log(
      "╚══════════════════════════════════════════════════════════════╝",
    );
    console.log("\n");
    log.info("Prochaines étapes:");
    console.log(
      "  1. Vérifie ton .env.local et complète les valeurs manquantes",
    );
    console.log("  2. Lance: pnpm dev");
    console.log("  3. Lance: mgw (pour mgrep watch)");
    console.log("\n");
  } catch (error) {
    log.error(`Erreur inattendue: ${error}`);
    process.exit(1);
  } finally {
    rl.close();
  }
}

