#!/usr/bin/env tsx
/* eslint-disable no-console */
/**
 * Setup interactif pour light-ts
 * Usage: pnpm setup
 *
 * Guide l'utilisateur pour configurer:
 * 1. Vérifier les CLIs (gh, vercel, neon, upstash, stripe)
 * 2. Configurer Vercel
 * 3. Configurer NeonDB (PostgreSQL)
 * 4. Configurer Upstash (Redis)
 * 5. Configurer Stripe (optionnel)
 * 6. Générer .env.local
 * 7. Migrer la DB
 */

import { execSync } from "child_process";
import * as fs from "fs";
import * as path from "path";
import * as readline from "readline";

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const question = async (prompt: string): Promise<string> =>
  new Promise((resolve) => rl.question(prompt, resolve));

const colors = {
  reset: "\x1b[0m",
  green: "\x1b[32m",
  red: "\x1b[31m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  dim: "\x1b[2m",
};

const log = {
  info: (msg: string) =>
    console.log(`${colors.blue}[INFO]${colors.reset} ${msg}`),
  success: (msg: string) =>
    console.log(`${colors.green}[OK]${colors.reset} ${msg}`),
  warn: (msg: string) =>
    console.log(`${colors.yellow}[WARN]${colors.reset} ${msg}`),
  error: (msg: string) =>
    console.log(`${colors.red}[ERREUR]${colors.reset} ${msg}`),
  step: (n: number, msg: string) =>
    console.log(`\n${colors.blue}[${n}/9]${colors.reset} ${msg}`),
};

function commandExists(cmd: string): boolean {
  try {
    execSync(`which ${cmd}`, { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

function isLoggedIn(cmd: string): boolean {
  try {
    switch (cmd) {
      case "gh":
        execSync("gh auth status", { stdio: "ignore" });
        return true;
      case "vercel":
        execSync("vercel whoami", { stdio: "ignore" });
        return true;
      case "neon":
        execSync("neon me", { stdio: "ignore" });
        return true;
      case "stripe":
        execSync("stripe config --list", { stdio: "ignore" });
        return true;
      case "upstash":
        execSync("upstash team list", { stdio: "ignore" });
        return true;
      case "mgrep":
        execSync("mgrep stores list", { stdio: "ignore" });
        return true;
      default:
        return false;
    }
  } catch {
    return false;
  }
}

function runCommand(
  cmd: string,
  options?: { stdio?: "inherit" | "ignore" },
): boolean {
  try {
    execSync(cmd, { stdio: options?.stdio ?? "inherit" });
    return true;
  } catch {
    return false;
  }
}

async function checkCLIs(): Promise<void> {
  log.step(1, "Vérification des CLIs...");

  const clis = [
    { name: "gh", label: "GitHub CLI", required: true },
    { name: "vercel", label: "Vercel CLI", required: true },
    { name: "neon", label: "NeonDB CLI", required: true },
    { name: "upstash", label: "Upstash CLI", required: true },
    { name: "stripe", label: "Stripe CLI", required: false },
    { name: "mgrep", label: "mgrep CLI", required: true },
    { name: "pnpm", label: "pnpm", required: true },
  ];

  for (const cli of clis) {
    if (!commandExists(cli.name)) {
      if (cli.required) {
        log.error(
          `${cli.label} n'est pas installé. Installe-le avec: npm i -g ${cli.name}`,
        );
        process.exit(1);
      } else {
        log.warn(`${cli.label} n'est pas installé (optionnel)`);
      }
    } else if (!isLoggedIn(cli.name) && cli.name !== "pnpm") {
      log.warn(`${cli.label} n'est pas connecté. Lance: ${cli.name} login`);
    } else {
      log.success(`${cli.label} OK`);
    }
  }
}

async function setupVercel(): Promise<Record<string, string>> {
  log.step(2, "Configuration Vercel...");

  const envVars: Record<string, string> = {};

  if (fs.existsSync(".vercel/project.json")) {
    log.info("Projet Vercel déjà lié");
    const pullEnv = await question(
